@@ -0,0 +1,33 @@
+// API keys and the audit log. Keys live in `apiKeys` ({ key, name, role });
+// every request that changes data leaves one entry in `audit`.
+import { timingSafeEqual } from "node:crypto";
+
+/** Roles, from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const same = (a, b) => {
+  const x = Buffer.from(a);
+  const y = Buffer.from(b);
+  return x.length === y.length && timingSafeEqual(x, y);
+};
+
+/** The API key record matching `key` (with a known role), or null. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) if (typeof k.key === "string" && same(k.key, key) && ROLES.includes(k.role)) found ??= k;
+  return found;
+}
+
+/** Appends an audit entry { at, keyName, method, path, status }; returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function auditLog(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
