+// Who may call which route. `viewer` reads, `cook` also does the kitchen's
+// daily work, `manager` does everything.
+
+// Routes a cook may call besides reads.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads only managers may make.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The key from an `Authorization: Bearer <key>` header, or null. */
+export function bearerKey(headers = {}) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const value = name ? headers[name] : undefined;
+  const m = typeof value === "string" ? /^Bearer\s+(\S+)\s*$/i.exec(value) : null;
+  return m ? m[1] : null;
+}
+
+/** Whether `role` may call the route "METHOD /pattern". */
+export function allowed(role, route) {
+  if (role === "manager") return true;
+  if (route.startsWith("GET ")) return !MANAGER_READS.has(route);
+  return role === "cook" && COOK_ROUTES.has(route);
+}
